/* Progressive HTML controls, reviewed with shadcn form/composition guidance.
   Native inputs remain the data contract; no React/shadcn runtime is installed. */
(()=>{'use strict';const panel=document.querySelector('#panel-body');let seq=0;
const change=el=>{el.dispatchEvent(new Event('input',{bubbles:true}));el.dispatchEvent(new Event('change',{bubbles:true}))};
function button(text,fn){const b=document.createElement('button');b.type='button';b.textContent=text;b.onclick=fn;return b}
function enhance(){
 panel.querySelectorAll('select:not([data-ui])').forEach(select=>{select.dataset.ui='ready';if(select.closest('[hidden]'))return;const options=Array.from(select.options);if(options.length<2||options.length>7)return;const label=select.closest('label'),name=label?.childNodes[0]?.textContent?.trim()||'选项';const group=document.createElement('div');group.className='option-pills';group.dataset.field=select.name;group.setAttribute('role','group');group.setAttribute('aria-label',name);options.forEach(o=>{if(!o.value&&select.required)return;const b=button(o.textContent,()=>{select.value=o.value;change(select);sync()});b.dataset.value=o.value;if(select.name==='stoolColor'){const dot=document.createElement('i');dot.className='color-swatch';dot.style.background=({'黄色':'#d4ae3f','棕色':'#916846','绿色':'#7f985b','其他':'#889199'})[o.value]||'transparent';b.prepend(dot)}group.append(b)});function sync(){group.querySelectorAll('button').forEach(b=>{b.setAttribute('aria-pressed',String(select.value===b.dataset.value))})}sync();select.classList.add('select-fallback');select.setAttribute('aria-label',name);label?.after(group);select.addEventListener('change',sync);select.addEventListener('invalid',()=>{select.classList.remove('select-fallback');select.setAttribute('aria-invalid','true')})});
 panel.querySelectorAll('input[type=number]:not([data-ui])').forEach(input=>{input.dataset.ui='ready';const configs={amount:{min:0,max:400,step:5,unit:'ml',values:[30,60,90,120,150]},weight:{min:1,max:25,step:.1,unit:'kg',values:[3,4,5,6,8]},duration:{min:0,max:240,step:5,unit:'分钟',values:[5,10,20,30,60]}};const c=configs[input.name];if(!c)return;const label=input.closest('label'),title=label?.childNodes[0]?.textContent?.trim()||input.name;const box=document.createElement('section');box.className='ruler-control';box.setAttribute('aria-label',title+'选择器');const output=document.createElement('output');output.className='ruler-value';const hint=document.createElement('p');hint.className='control-hint';hint.textContent='滑动刻度或点选快捷值；不会自动保存默认数值。';const range=document.createElement('input');range.type='range';range.min=c.min;range.max=c.max;range.step=c.step;range.value=input.value||c.values[2];range.setAttribute('aria-label',title+'滑动刻度');const scale=document.createElement('div');scale.className='ruler-ticks';scale.setAttribute('aria-hidden','true');scale.innerHTML=`<span>${c.min}</span><span>${(c.max+c.min)/2}</span><span>${c.max} ${c.unit}</span>`;const presets=document.createElement('div');presets.className='preset-values';c.values.forEach(v=>presets.append(button(v+' '+c.unit,()=>set(v))));const stepper=document.createElement('div');stepper.className='ruler-stepper';stepper.append(button('−',()=>set(Math.max(c.min,Number(input.value||range.value)-c.step))),output,button('＋',()=>set(Math.min(c.max,Number(input.value||range.value)+c.step))));stepper.firstChild.setAttribute('aria-label','减少'+c.step+c.unit);stepper.lastChild.setAttribute('aria-label','增加'+c.step+c.unit);box.append(stepper,range,scale,presets,hint);const exact=document.createElement('details');exact.className='exact-input';const sum=document.createElement('summary');sum.textContent='精确输入 / 超出刻度范围';exact.append(sum);label.before(box,exact);exact.append(label);input.placeholder='输入准确数值';input.id=input.id||'exact-'+(++seq);range.setAttribute('aria-controls',input.id);function sync(){output.textContent=input.value===''?'请选择':input.value+' '+c.unit;range.setAttribute('aria-valuetext',input.value===''?'尚未选择':input.value+' '+c.unit);if(input.value!=='')range.value=input.value;presets.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b.textContent===input.value+' '+c.unit)))}function set(v){input.value=String(Math.round(v*10)/10);sync();change(input)}range.addEventListener('input',()=>set(Number(range.value)));input.addEventListener('input',sync);input.addEventListener('invalid',()=>{exact.open=true;input.setAttribute('aria-invalid','true')});sync()});
 panel.querySelectorAll('input[type=datetime-local]:not([data-ui])').forEach(input=>{input.dataset.ui='ready';const wrap=document.createElement('div');wrap.className='preset-values';const future=input.name==='due';(future?[['30分钟后',30],['1小时后',60],['明天此时',1440]]:[['现在',0],['10分钟前',-10],['30分钟前',-30],['1小时前',-60]]).forEach(([t,m])=>wrap.append(button(t,()=>{const d=new Date(Date.now()+m*60000);input.value=new Date(d-d.getTimezoneOffset()*60000).toISOString().slice(0,16);change(input)})));input.closest('label')?.after(wrap)});
 panel.querySelectorAll('textarea[name=note]:not([data-ui])').forEach(el=>{el.dataset.ui='ready';const label=el.closest('label'),d=document.createElement('details');d.className='optional-field';d.open=!!el.value;d.innerHTML='<summary>添加备注（可选）</summary>';label.before(d);d.append(label)});
 panel.querySelectorAll('input[name=title]:not([data-ui])').forEach(input=>{input.dataset.ui='ready';const wrap=document.createElement('div');wrap.className='preset-values';['补记喂养','记录体重','回顾今天'].forEach(t=>wrap.append(button(t,()=>{input.value=t;change(input)})));input.closest('label')?.after(wrap)});
 panel.querySelectorAll('form').forEach(f=>{f.classList.add('guided-form');f.querySelectorAll('input,select,textarea').forEach(el=>{if(el.dataset.errorBound)return;el.dataset.errorBound='1';el.addEventListener('invalid',()=>{el.setAttribute('aria-invalid','true');el.closest('details')?.setAttribute('open','')});el.addEventListener('input',()=>el.removeAttribute('aria-invalid'))})});
}
new MutationObserver(enhance).observe(panel,{childList:true,subtree:true});enhance();
})();
